package com.bank.portal.domain; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import lombok.*;
@Entity @Table(name="credit_limit_requests") @Getter @Setter @NoArgsConstructor public class CreditLimitRequest extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @ManyToOne(optional=false) @JoinColumn(name="card_id") private CreditCard card; @Column(nullable=false,precision=15,scale=2) private BigDecimal currentLimit; @Column(nullable=false,precision=15,scale=2) private BigDecimal requestedLimit; @Column(nullable=false) private String reason; @Enumerated(EnumType.STRING) @Column(nullable=false) private CreditLimitRequestStatus status; private String reviewedBy; private LocalDateTime reviewedAt; private String reviewComment; }
